import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

export const dynamic = "force-dynamic";

/**
 * GET /api/ops/he_report — Task 85: הדוח-העברי-החי לקונסולה.
 *
 * Reads docs/REPORT_HE.md (generated by the daemon's heReport cycle every
 * 30 min via agent/he_report.cjs and pushed to the repo by gitkeeper) and
 * serves it to the console so the operator always has a Hebrew report —
 * in the repo AND in the UI. Never 500s: a missing report is a state.
 */
export async function GET() {
  const file = path.join(process.cwd(), "docs", "REPORT_HE.md");
  try {
    const [markdown, stat] = await Promise.all([fs.readFile(file, "utf8"), fs.stat(file)]);
    return NextResponse.json(
      { at: new Date().toISOString(), mtime: stat.mtime.toISOString(), markdown },
      { headers: { "cache-control": "no-store" } },
    );
  } catch (e) {
    return NextResponse.json(
      { at: new Date().toISOString(), markdown: null, error: String((e as Error).message || e).slice(0, 120) },
      { headers: { "cache-control": "no-store" } },
    );
  }
}
